function stripCodeFences(s) {
  return String(s || '').trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
}

function toNumber(v) {
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

const webhookBody = $('Webhook1').first().json.body;
const rawText = $json.content.parts[0].text;
const cleaned = stripCodeFences(rawText);

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { items: [], itemCount: 0 };
}

const globalQuantity = toNumber(parsed.itemCount) || 1;
let items = Array.isArray(parsed.items) ? parsed.items : [];

items = items.map((item) => {
  const isDoor = String(item.type || '').toLowerCase().includes('door');
  return {
    width_mm: toNumber(item.width_mm),
    height_mm: toNumber(item.height_mm) ?? (isDoor ? 2100 : null),
    quantity: toNumber(item.quantity) || globalQuantity,
    type: String(item.type || 'window'),
    glassType: String(item.glass_type || 'clear'),
    thickness: toNumber(item.thickness_mm) ?? (isDoor ? 10 : 6),
    frameColor: item.frame_color || item.frameColor || 'White',
    openingMechanism: String(item.opening_mechanism || 'unknown'),
  };
}).filter(i => i.width_mm);

const lines = items.map((item, idx) => {
  return [
    `Item ${idx + 1}: ${String(item.type).toUpperCase()}`,
    `📐 Size: ${item.width_mm}mm x ${item.height_mm}mm`,
    `🔢 Qty: ${item.quantity}`,
    `💎 Glass: ${item.glassType} (${item.thickness}mm)`,
    `🎨 Frame: ${item.frameColor}`
  ].join('\n');
});

const confirmationText = items.length === 0
  ? `I couldn't extract measurements from your message. Please try again with format: "1200 x 800 window white clear x5".`
  : `Please confirm these are your measurement:\n\n${lines.join('\n\n')}\n\nReply "YES" to proceed or "REDO TEXT" to start over.`;

return [{
  json: {
    chat_id: webhookBody.chat_id,
    items,
    itemsString: JSON.stringify(items),
    confirmationText
  }
}];
